sql.processStepStatus.insertType:

insert into flow.company_process_step_status_type(process_step_status_type, process_step_status_type_id, created_by_id, company_id, date_created)
  values (:processStepStatusType, :processStepStatusTypeId, :createdById, :companyId, now())
returning id;

sql.processStepStatus.saveInitialProcessStep:

update flow.company_process_step_status_type
set is_default = false
where company_id = :companyId;
update flow.company_process_step_status_type
set is_default = true
where id = :id;
